// Local, self-contained SVG assets; dimensions are rasterization sizes, not physics sizes.
export const ART_ASSETS = Object.freeze([
  { key: 'art2d-karakurt', file: 'karakurt.svg', width: 256, height: 256 },
  { key: 'art2d-human-slipper', file: 'human-slipper.svg', width: 384, height: 768 },
  { key: 'art2d-memory', file: 'memory.svg', width: 256, height: 256 },
  { key: 'art2d-living-room-far', file: 'living-room-far.svg', width: 1600, height: 900 },
  { key: 'art2d-living-room-near', file: 'living-room-near.svg', width: 1600, height: 900 },
  { key: 'art2d-kitchen-far', file: 'kitchen-far.svg', width: 1600, height: 900 },
  { key: 'art2d-kitchen-near', file: 'kitchen-near.svg', width: 1600, height: 900 },
]);

// Phaser's XHR loader decodes data URLs with atob, so percent-encoded SVG is not supported.
export function svgDataUri(source) {
  const bytes = new TextEncoder().encode(source);
  return `data:image/svg+xml;base64,${btoa(Array.from(bytes, byte => String.fromCharCode(byte)).join(''))}`;
}

export function spiderBodySource(source) {
  const document = new DOMParser().parseFromString(source, 'image/svg+xml');
  const body = document.getElementById('body');
  if (!body || document.querySelector('parsererror')) return null;
  const root = document.documentElement.cloneNode(false);
  for (const defs of document.documentElement.querySelectorAll(':scope > defs')) root.appendChild(defs.cloneNode(true));
  root.appendChild(body.cloneNode(true));
  return new XMLSerializer().serializeToString(root);
}

export function roomArtKeys(templateId) {
  const name = { LivingRoom: 'living-room', Kitchen: 'kitchen' }[templateId];
  return name ? [`art2d-${name}-far`, `art2d-${name}-near`] : null;
}

// A fixed room camera cannot produce scrollFactor parallax on its own.
export function parallaxOffsets(playerX = 960) {
  const offset = Math.max(-960, Math.min(960, playerX - 960));
  return { far: -offset * .018, near: -offset * .045 };
}

